/** Params type carried by a `defineWorkflow` definition (its phantom `__params`). */
type WorkflowParamsOf<Definition> = Definition extends { __params?: infer Params } ? (unknown extends Params ? Record<string, unknown> : Params) : Record<string, unknown>;

/** A typed reference to a durable workflow, addressable for `cronJobs()` targets. Mirrors `@lunora/scheduler`'s `WorkflowReference` structurally. */
export interface WorkflowReference<Params = Record<string, unknown>> {
    readonly isLunoraWorkflow: true;
    readonly __params?: Params;
    readonly className: string;
    readonly name: string;
}

/** This project's durable workflows, addressable as typed references (e.g. `crons.daily("digest", …, workflows.digestPipeline, params)`). */
export interface WorkflowsRef {
    accountDeletionWorkflow: WorkflowReference<WorkflowParamsOf<typeof lunoraWorkflowDefinitions.accountDeletionWorkflow>>;
    chatImportWorkflow: WorkflowReference<WorkflowParamsOf<typeof lunoraWorkflowDefinitions.chatImportWorkflow>>;
    dataExportWorkflow: WorkflowReference<WorkflowParamsOf<typeof lunoraWorkflowDefinitions.dataExportWorkflow>>;
}

export const workflows: WorkflowsRef = {
    accountDeletionWorkflow: { isLunoraWorkflow: true, className: "AccountDeletionWorkflowWorkflow", name: "accountDeletionWorkflow" },
    chatImportWorkflow: { isLunoraWorkflow: true, className: "ChatImportWorkflowWorkflow", name: "chatImportWorkflow" },
    dataExportWorkflow: { isLunoraWorkflow: true, className: "DataExportWorkflowWorkflow", name: "dataExportWorkflow" },
};
